UPDATE oc_learning_questions SET
  text = 'Ein Netzwerktechniker hat einen Access-Layer-Switch (SW1) ausgetauscht und muss diesen neu konfigurieren. PC3 wurde kürzlich in VLAN 90 (Management) versetzt, aber der Port ist noch nicht konfiguriert. Außerdem soll der LACP-Port-Channel zwischen SW1 und SW2 überprüft werden. Analysieren Sie die aktuelle Konfiguration und führen Sie die notwendigen Änderungen durch.',
  explanation = 'Lösung: Auf SW1 → conf t → interface gi0/3 → switchport mode access → switchport access vlan 90. Der LACP Port-Channel 1 (Gi0/7+Gi0/8) läuft bereits korrekt mit ''channel-group 1 mode active'' (802.3ad). SW2 zeigt VLAN 90 auf Gi0/2 (Management-PC) korrekt. Das Problem: Port Gi0/3 (PC3) war unkonfiguriert und hatte keine VLAN-Zuweisung — Standard-VLAN 1 statt VLAN 90.',
  pbq_subtype = 'cli',
  pbq_config = '{"scenario_image": "data:image/svg+xml;base64,", "domain": "cisco_ios", "hint": "Verfügbare Befehle: show vlan brief | show interfaces trunk | show running-config | show etherchannel summary | show lacp neighbor | conf t | interface gi0/3 | switchport access vlan 90 | channel-group 1 mode active | end", "terminals": [{"name": "SW1", "welcome": "Cisco IOS Software, Version 15.2(4)M5\nCopyright (c) 1986-2014 by Cisco Systems, Inc.\n\nSW1 uptime is 2 days, 4 hours, 12 minutes"}, {"name": "SW2", "welcome": "Cisco IOS Software, Version 15.2(4)M5\nCopyright (c) 1986-2014 by Cisco Systems, Inc.\n\nSW2 uptime is 2 days, 4 hours, 12 minutes"}], "command_outputs": {"SW1": {"show vlan brief": "VLAN Name                             Status    Ports\n---- -------------------------------- --------- -------------------------------\n1    default                          active    Gi0/6, Gi0/7, Gi0/8\n10   USERS                            active    Gi0/1\n20   MARKETING                        active    Gi0/2\n30   PRINTING                         active    Gi0/4\n60   CCTV                             active    Gi0/5\n90   MANAGEMENT                       active\n1002 fddi-default                     act/unsup\n1003 token-ring-default               act/unsup\n", "show interfaces trunk": "Port      Mode         Encapsulation  Status        Native vlan\nGi0/7     on           802.1q         trunking      1\nGi0/8     on           802.1q         trunking      1\n\nPort      Vlans allowed on trunk\nGi0/7     1-4094\nGi0/8     1-4094\n\nPort      Vlans allowed and active in management domain\nGi0/7     1,10,20,30,60,90\nGi0/8     1,10,20,30,60,90\n\nPort      Vlans in spanning tree forwarding state and not pruned\nGi0/7     1,10,20,30,60,90\nGi0/8     1,10,20,30,60,90\n", "show running-config": "Building configuration...\n\ninterface GigabitEthernet0/1\n description PC1\n switchport mode access\n switchport access vlan 10\n spanning-tree portfast\n!\ninterface GigabitEthernet0/2\n description PC2\n switchport mode access\n switchport access vlan 20\n spanning-tree portfast\n!\ninterface GigabitEthernet0/3\n description PC3 - NEWLY ADDED (UNCONFIGURED)\n switchport mode access\n!\ninterface GigabitEthernet0/4\n description Drucker\n switchport mode access\n switchport access vlan 30\n!\ninterface GigabitEthernet0/5\n description CCTV-Kamera\n switchport mode access\n switchport access vlan 60\n!\ninterface GigabitEthernet0/7\n description Uplink-to-SW2-ch1\n switchport mode trunk\n channel-group 1 mode on\n!\ninterface GigabitEthernet0/8\n description Uplink-to-SW2-ch2\n switchport mode trunk\n channel-group 1 mode on\n!\ninterface Port-channel1\n description LAG-zu-SW2\n switchport mode trunk\n!\n", "show etherchannel summary": "Group  Port-channel  Protocol    Ports\n------+-------------+-----------+-----------------------------------------------\n1      Po1(SU)         LACP      Gi0/7(P) Gi0/8(P)\n\nFlags:  D - down        P - bundled in port-channel\n        I - stand-alone s - suspended\n        H - Hot-standby\n        U - in use      S/s - short/long timeout\n        N - not in use, Min-links not met\n        w - waiting to be aggregated\n", "show lacp neighbor": "Flags:  S - Device is sending Slow LACPDUs   F - Device is sending Fast LACPDUs\n        A - Device is in Active mode          P - Device is in Passive mode\n\nChannel group 1\n                            LACP port     Admin     Oper    Port        Port\nPort      Flags   State     Priority      Key       Key     Number      State\nGi0/7     SA      bndl      32768         0x1       0x1     0x103       0x3D\nGi0/8     SA      bndl      32768         0x1       0x1     0x104       0x3D\n", "conf t": "", "configure terminal": "", "interface gi0/3": "", "interface gigabitethernet0/3": "", "switchport mode access": "% Switchport mode set to access on GigabitEthernet0/3.", "switchport access vlan 90": "% VLAN 90 assigned to GigabitEthernet0/3.", "channel-group 1 mode active": "Creating a port-channel interface Port-channel 1\n% LACP mode set to active on GigabitEthernet0/3.", "exit": "", "end": ""}, "SW2": {"show vlan brief": "VLAN Name                             Status    Ports\n---- -------------------------------- --------- -------------------------------\n1    default                          active    Gi0/3, Gi0/4\n10   USERS                            active    Gi0/1\n20   MARKETING                        active\n30   PRINTING                         active\n60   CCTV                             active\n90   MANAGEMENT                       active    Gi0/2\n1002 fddi-default                     act/unsup\n1003 token-ring-default               act/unsup\n", "show interfaces trunk": "Port      Mode         Encapsulation  Status        Native vlan\nGi0/7     on           802.1q         trunking      1\nGi0/8     on           802.1q         trunking      1\nGi0/2     on           802.1q         trunking      1\n\nPort      Vlans allowed on trunk\nGi0/7     1-4094\nGi0/8     1-4094\nGi0/2     1-4094\n", "show running-config": "interface GigabitEthernet0/1\n description File-Server\n switchport mode access\n switchport access vlan 10\n!\ninterface GigabitEthernet0/2\n description Management-PC\n switchport mode access\n switchport access vlan 90\n!\ninterface GigabitEthernet0/7\n description Uplink-to-SW1-ch1\n switchport mode trunk\n channel-group 1 mode active\n!\ninterface GigabitEthernet0/8\n description Uplink-to-SW1-ch2\n switchport mode trunk\n channel-group 1 mode active\n", "conf t": "", "configure terminal": "", "exit": "", "end": ""}}, "evaluation": [{"terminal": "SW1", "required_pattern": "switchport access vlan 90", "points": 3, "explanation": "Port Gi0/3 (PC3) muss VLAN 90 zugewiesen werden. Befehlsfolge: conf t → interface gi0/3 → switchport access vlan 90"}, {"terminal": "SW1", "required_pattern": "show vlan brief", "points": 1, "explanation": "Vor der Konfiguration die aktuelle VLAN-Zuweisung prüfen"}, {"terminal": "SW2", "required_pattern": "show interfaces trunk", "points": 1, "explanation": "Trunk-Konfiguration auf SW2 verifizieren"}]}'::jsonb
WHERE id = 12460;

UPDATE oc_learning_questions SET
  text = 'Ein Netzwerktechniker wurde kürzlich eingestellt und soll das Netzwerk dokumentieren. Der Manager vermutet, dass es Verbindungsprobleme gibt, weil sich die MAC-Adresstabelle ständig ändert und die Routing-Tabellen veraltet sein könnten. Analysieren Sie die MAC-Adresstabellen auf SW1 und SW2 sowie die Routing-Informationen, um die Netzwerktopologie zu kartieren.',
  explanation = 'Lösung: show mac address-table auf SW1 zeigt mehrfache MAC-Einträge für dieselben Adressen auf unterschiedlichen Ports — ein Hinweis auf eine mögliche Loop-Situation oder ein falsch konfigurierten Trunk. show running-config bestätigt die VLAN-Zuweisungen. Die Routing-Tabelle zeigt statische Default-Route über 10.0.0.1. Alle Informationen werden für die Netzwerkdokumentation benötigt.',
  pbq_subtype = 'cli',
  pbq_config = '{"scenario_image": "data:image/svg+xml;base64,", "domain": "cisco_ios", "hint": "Verfügbare Befehle: show mac address-table | show mac address-table dynamic | show mac address-table static | show ip route | show running-config | show interfaces | show vlan brief", "terminals": [{"name": "SW1", "welcome": "Cisco IOS Software, Version 15.2(4)M5\n\nSW1 uptime is 3 days, 2 hours"}, {"name": "SW2", "welcome": "Cisco IOS Software, Version 15.2(4)M5\n\nSW2 uptime is 3 days, 2 hours"}], "command_outputs": {"SW1": {"show mac address-table": "          Mac Address Table\n-------------------------------------------\n\nVlan    Mac Address       Type        Ports\n----    -----------       --------    -----\n  10    0012.7f3a.0001    DYNAMIC     Gi0/1\n  10    0012.7f3a.0002    DYNAMIC     Gi0/24\n  20    0012.7f3a.0003    DYNAMIC     Gi0/2\n  20    0012.7f3a.0003    DYNAMIC     Gi0/24\n  10    0012.7f3a.0002    DYNAMIC     Gi0/1\n  10    0012.7f3a.0002    DYNAMIC     Gi0/24\n  30    0012.7f3a.0099    DYNAMIC     Gi0/3\nTotal Mac Addresses for this criterion: 7\n", "show mac address-table dynamic": "          Mac Address Table\n-------------------------------------------\n\nVlan    Mac Address       Type        Ports\n----    -----------       --------    -----\n  10    0012.7f3a.0001    DYNAMIC     Gi0/1\n  10    0012.7f3a.0002    DYNAMIC     Gi0/24\n  20    0012.7f3a.0003    DYNAMIC     Gi0/2\n  20    0012.7f3a.0003    DYNAMIC     Gi0/24\n  10    0012.7f3a.0002    DYNAMIC     Gi0/1\n  10    0012.7f3a.0002    DYNAMIC     Gi0/24\n  30    0012.7f3a.0099    DYNAMIC     Gi0/3\nTotal Mac Addresses for this criterion: 7\n", "show mac address-table static": "          Mac Address Table\n-------------------------------------------\n\nVlan    Mac Address       Type        Ports\n----    -----------       --------    -----\nTotal Mac Addresses for this criterion: 0\n", "show ip route": "Codes: C - connected, S - static, R - RIP, M - mobile, B - BGP\n       D - EIGRP, EX - EIGRP external, O - OSPF, IA - OSPF inter area\n\nGateway of last resort is 10.0.0.1 to network 0.0.0.0\n\nC     10.0.0.0/24 is directly connected, Vlan10\nC     10.0.1.0/24 is directly connected, Vlan20\nS*    0.0.0.0/0 [1/0] via 10.0.0.1\n", "show running-config": "interface GigabitEthernet0/1\n description PC1-VLAN10\n switchport mode access\n switchport access vlan 10\n!\ninterface GigabitEthernet0/2\n description PC2-VLAN20\n switchport mode access\n switchport access vlan 20\n!\ninterface GigabitEthernet0/3\n description Drucker-VLAN30\n switchport mode access\n switchport access vlan 30\n!\ninterface GigabitEthernet0/24\n description Trunk-to-SW2\n switchport mode trunk\n", "show vlan brief": "VLAN Name                             Status    Ports\n---- -------------------------------- --------- -------------------------------\n1    default                          active    Gi0/6, Gi0/7, Gi0/8\n10   USERS                            active    Gi0/1\n20   MARKETING                        active    Gi0/2\n30   PRINTING                         active    Gi0/4\n60   CCTV                             active    Gi0/5\n90   MANAGEMENT                       active\n1002 fddi-default                     act/unsup\n1003 token-ring-default               act/unsup\n", "show interfaces": "GigabitEthernet0/1 is up, line protocol is up\n  Hardware is Gigabit Ethernet\n  MTU 1500 bytes, BW 1000000 Kbit/sec\n  0 input errors, 0 CRC\n\nGigabitEthernet0/24 is up, line protocol is up\n  Hardware is Gigabit Ethernet\n  MTU 1500 bytes, BW 1000000 Kbit/sec\n  0 input errors, 0 CRC\n"}, "SW2": {"show mac address-table": "          Mac Address Table\n-------------------------------------------\n\nVlan    Mac Address       Type        Ports\n----    -----------       --------    -----\n  10    0012.7f3a.0001    DYNAMIC     Gi0/24\n  10    00aa.bbcc.0001    DYNAMIC     Gi0/1\n  20    0012.7f3a.0003    DYNAMIC     Gi0/24\nTotal Mac Addresses for this criterion: 3\n", "show mac address-table dynamic": "          Mac Address Table\n-------------------------------------------\n\nVlan    Mac Address       Type        Ports\n----    -----------       --------    -----\n  10    0012.7f3a.0001    DYNAMIC     Gi0/24\n  10    00aa.bbcc.0001    DYNAMIC     Gi0/1\n  20    0012.7f3a.0003    DYNAMIC     Gi0/24\nTotal Mac Addresses for this criterion: 3\n", "show ip route": "Codes: C - connected, S - static, R - RIP, M - mobile, B - BGP\n       D - EIGRP, EX - EIGRP external, O - OSPF, IA - OSPF inter area\n\nGateway of last resort is 10.0.0.1 to network 0.0.0.0\n\nC     10.0.0.0/24 is directly connected, Vlan10\nC     10.0.1.0/24 is directly connected, Vlan20\nS*    0.0.0.0/0 [1/0] via 10.0.0.1\n", "show running-config": "interface GigabitEthernet0/1\n description File-Server\n switchport mode access\n switchport access vlan 10\n!\ninterface GigabitEthernet0/23\n description Uplink-to-Router\n switchport mode trunk\n!\ninterface GigabitEthernet0/24\n description Trunk-to-SW1\n switchport mode trunk\n", "show vlan brief": "VLAN Name                             Status    Ports\n---- -------------------------------- --------- -------------------------------\n1    default                          active    Gi0/3, Gi0/4\n10   USERS                            active    Gi0/1\n20   MARKETING                        active\n30   PRINTING                         active\n60   CCTV                             active\n90   MANAGEMENT                       active    Gi0/2\n1002 fddi-default                     act/unsup\n1003 token-ring-default               act/unsup\n", "show interfaces": "GigabitEthernet0/1 is up, line protocol is up\n  Hardware is Gigabit Ethernet\n  Description: File-Server\n  0 input errors\n\nGigabitEthernet0/24 is up, line protocol is up\n  Hardware is Gigabit Ethernet\n  Description: Trunk-to-SW1\n  0 input errors\n"}}, "evaluation": [{"terminal": "SW1", "required_pattern": "show mac address-table", "points": 2, "explanation": "MAC-Adresstabelle anzeigen: zeigt welche Geräte an welchen Ports eingetragen sind (dynamisch vs. statisch)"}, {"terminal": "SW2", "required_pattern": "show mac address-table", "points": 2, "explanation": "Auch SW2 MAC-Tabelle prüfen um die vollständige Topologie zu kartieren"}, {"terminal": "SW1", "required_pattern": "show running-config", "points": 1, "explanation": "Running-Config zeigt die aktuelle Konfiguration inkl. VLAN-Zuweisungen und Trunk-Ports"}]}'::jsonb
WHERE id = 12465;

UPDATE oc_learning_questions SET
  text = 'Benutzer können nicht auf Dateien der Abteilungsfreigabe auf Dateiserver 2 (10.0.4.x) zugreifen. Überprüfen Sie das Routing zwischen Router A, Router B und Router C. Die Netzwerkkarte zeigt: Router A verbindet die Clients (10.0.5.0/24, 10.0.6.0/24) über 10.0.0.0/22 mit Router B. Router B verbindet über 10.0.4.0/22 mit Router C. Router C hostet Dateiserver 2 im 10.0.4.0/22 Netz. Identifizieren Sie die Routing-Lücke.',
  explanation = 'Lösung: Router A hat keine Route zu 10.0.4.0/22 (außerhalb des /22 von Gi3). OSPF-Routing zeigt: Router B kennt 10.0.4.0/22 (direkt, Gi1) und 10.0.0.0/24 (direkt, Gi3), aber Router A sieht nur 10.0.0.0/22 als direkt verbunden. Das Problem: Router A''s Gi3 ist 10.0.0.0/22 — das enthält 10.0.0.x, 10.0.1.x, 10.0.2.x, 10.0.3.x, aber NICHT 10.0.4.0/22. Router B muss eine Route nach 10.0.4.0/22 an Router A via OSPF weitergeben. Router C fehlen Routes zu den Client-Netzen.',
  pbq_subtype = 'cli',
  pbq_config = '{"scenario_image": "data:image/svg+xml;base64,", "domain": "cisco_ios", "hint": "Verfügbare Befehle: show ip route | show ip interface brief | show running-config | ping [IP] | traceroute [IP]", "terminals": [{"name": "Router A", "welcome": "Cisco IOS Software, Version 15.4(3)M2\n\nRouter A uptime is 0 days, 0 hours, 42 minutes\nHINWEIS: Dateiserver 2 (10.0.4.x) wird gemeldet als nicht erreichbar"}, {"name": "Router B", "welcome": "Cisco IOS Software, Version 15.4(3)M2\n\nRouter B uptime is 2 days, 14 hours, 05 minutes"}, {"name": "Router C", "welcome": "Cisco IOS Software, Version 15.4(3)M2\n\nRouter C uptime is 2 days, 14 hours, 10 minutes"}], "command_outputs": {"Router A": {"show ip route": "Codes: C - connected, S - static, R - RIP, M - mobile, B - BGP\n       D - EIGRP, EX - EIGRP external, O - OSPF\n\nGateway of last resort is not set\n\nC     10.0.5.0/24 is directly connected, GigabitEthernet1\nC     10.0.6.0/24 is directly connected, GigabitEthernet2\nC     10.0.0.0/22 is directly connected, GigabitEthernet3\nO     10.0.1.0/24 [110/2] via 10.0.0.2, 00:14:22, GigabitEthernet3\n", "show ip interface brief": "Interface                  IP-Address      OK? Method Status                Protocol\nGigabitEthernet1           10.0.5.1        YES NVRAM  up                    up\nGigabitEthernet2           10.0.6.1        YES NVRAM  up                    up\nGigabitEthernet3           10.0.0.1        YES NVRAM  up                    up\nGigabitEthernet4           unassigned      YES NVRAM  administratively down down\n", "show running-config": "interface GigabitEthernet1\n ip address 10.0.5.1 255.255.255.0\n!\ninterface GigabitEthernet2\n ip address 10.0.6.1 255.255.255.0\n!\ninterface GigabitEthernet3\n ip address 10.0.0.1 255.255.252.0\n!\nrouter ospf 1\n network 10.0.0.0 0.0.3.255 area 0\n network 10.0.5.0 0.0.0.255 area 0\n network 10.0.6.0 0.0.0.255 area 0\n", "ping 10.0.4.1": "Type escape sequence to abort.\nSending 5, 100-byte ICMP Echos to 10.0.4.1, timeout is 2 seconds:\n.....\nSuccess rate is 0 percent (0/5)\n% No route to 10.0.4.0/22 found in routing table.", "traceroute 10.0.4.1": "Type escape sequence to abort.\nTracing the route to 10.0.4.1\n\n  1  * * *\n  2  * * *\n% Destination unreachable."}, "Router B": {"show ip route": "Codes: C - connected, S - static, R - RIP, M - mobile, B - BGP\n       D - EIGRP, EX - EIGRP external, O - OSPF\n\nGateway of last resort is not set\n\nC     10.0.4.0/22 is directly connected, GigabitEthernet1\nC     10.0.1.0/24 is directly connected, GigabitEthernet2\nC     10.0.0.0/24 is directly connected, GigabitEthernet3\nO     10.0.5.0/24 [110/2] via 10.0.0.1, 00:14:22, GigabitEthernet3\nO     10.0.6.0/24 [110/2] via 10.0.0.1, 00:14:22, GigabitEthernet3\n", "show ip interface brief": "Interface                  IP-Address      OK? Method Status                Protocol\nGigabitEthernet1           10.0.4.1        YES NVRAM  up                    up\nGigabitEthernet2           10.0.1.1        YES NVRAM  up                    up\nGigabitEthernet3           10.0.0.2        YES NVRAM  up                    up\n", "show running-config": "interface GigabitEthernet1\n ip address 10.0.4.1 255.255.252.0\n!\ninterface GigabitEthernet2\n ip address 10.0.1.1 255.255.255.0\n!\ninterface GigabitEthernet3\n ip address 10.0.0.2 255.255.255.0\n!\nrouter ospf 1\n network 10.0.0.0 0.0.0.255 area 0\n network 10.0.1.0 0.0.0.255 area 0\n network 10.0.4.0 0.0.3.255 area 0\n", "ping 10.0.5.1": "Type escape sequence to abort.\nSending 5, 100-byte ICMP Echos to 10.0.5.1, timeout is 2 seconds:\n!!!!!\nSuccess rate is 100 percent (5/5), round-trip min/avg/max = 1/2/4 ms", "ping 10.0.4.1": "Type escape sequence to abort.\nSending 5, 100-byte ICMP Echos to 10.0.4.1, timeout is 2 seconds:\n!!!!!\nSuccess rate is 100 percent (5/5), round-trip min/avg/max = 1/1/2 ms"}, "Router C": {"show ip route": "Codes: C - connected, S - static, R - RIP, M - mobile, B - BGP\n       D - EIGRP, EX - EIGRP external, O - OSPF\n\nGateway of last resort is not set\n\nC     10.0.0.0/22 is directly connected, GigabitEthernet1\nC     10.0.4.0/22 is directly connected, GigabitEthernet2\n", "show ip interface brief": "Interface                  IP-Address      OK? Method Status                Protocol\nGigabitEthernet1           10.0.0.3        YES NVRAM  up                    up\nGigabitEthernet2           10.0.4.1        YES NVRAM  up                    up\n", "show running-config": "interface GigabitEthernet1\n ip address 10.0.0.3 255.255.252.0\n!\ninterface GigabitEthernet2\n ip address 10.0.4.1 255.255.252.0\n!\nrouter ospf 1\n network 10.0.0.0 0.0.3.255 area 0\n network 10.0.4.0 0.0.3.255 area 0\n", "ping 10.0.5.1": "Type escape sequence to abort.\nSending 5, 100-byte ICMP Echos to 10.0.5.1, timeout is 2 seconds:\n.....\nSuccess rate is 0 percent (0/5)\n% Kein Pfad zu 10.0.5.0/24 bekannt."}}, "evaluation": [{"terminal": "Router A", "required_pattern": "show ip route", "points": 2, "explanation": "Router A: show ip route zeigt, dass 10.0.4.0/22 (Dateiserver 2) nicht in der Routing-Tabelle steht. OSPF hat das Netz nicht propagiert."}, {"terminal": "Router B", "required_pattern": "show ip route", "points": 2, "explanation": "Router B: Hat 10.0.4.0/22 direkt verbunden (Gi1) und sieht die Routes von A und C über OSPF"}, {"terminal": "Router C", "required_pattern": "show ip route", "points": 2, "explanation": "Router C: Hat 10.0.4.0/22 direkt verbunden aber keine Route zu 10.0.5.0/24 oder 10.0.6.0/24 — OSPF-Nachbarschaft zu Router B prüfen"}]}'::jsonb
WHERE id = 12461;

UPDATE oc_learning_questions SET
  text = 'Ein Netzwerkadministrator soll eine Netzwerktopologie für ein neues Bürogebäude entwerfen. Das Diagramm zeigt 4 leere Positionen im Netzwerk. Weisen Sie jedem Gerät (A, B, C, D) die richtige Netzwerkkomponente zu: Die Verbindung zum Internet benötigt Sicherheit, das interne Routing muss zwischen Segmenten vermitteln, zwei Wireless-Bereiche müssen abgedeckt werden (Büro-Bereich mit eigenem SSID, Erweiterungsbereich der das Signal weiterleitet). Ein Switch ist bereits platziert.',
  explanation = 'Lösung: Gerät A (Internet-Gateway) = Firewall — trennt Internet von LAN und filtert Datenverkehr. Gerät B (LAN-Verbindung unter der Firewall) = Router — verbindet verschiedene Netzsegmente. Gerät C (Büro-Bereich, eigenes SSID) = WAP (Wireless Access Point) — stellt WLAN mit eigenem SSID für Bürogeräte bereit. Gerät D (Erweiterungsbereich) = Wireless Range Extender — verstärkt und erweitert das bestehende WLAN-Signal ohne eigenes Netz. Reihenfolge: Internet → Firewall → Router → Switch → WAP / Wireless Range Extender.',
  pbq_subtype = 'placement',
  pbq_config = '{"scenario_image": "data:image/svg+xml;base64,", "positions": [{"id": "pos_internet_gw", "label": "Gerät A — Internet-Gateway (direkt unter der Cloud)", "x_pct": 50, "y_pct": 36, "correct": "Firewall"}, {"id": "pos_router", "label": "Gerät B — LAN-Verbindungsgerät (unter der Firewall)", "x_pct": 50, "y_pct": 54, "correct": "Router"}, {"id": "pos_wap", "label": "Gerät C — Wireless-Gerät im Büro-Bereich (unten links)", "x_pct": 16, "y_pct": 88, "correct": "WAP"}, {"id": "pos_wre", "label": "Gerät D — Wireless-Gerät im Erweiterungsbereich (unten rechts)", "x_pct": 84, "y_pct": 88, "correct": "Wireless Range Extender"}], "device_options": ["Firewall", "Router", "WAP", "Wireless Range Extender", "Switch", "Hub"], "scoring_mode": "partial"}'::jsonb
WHERE id = 12468;

UPDATE oc_learning_questions SET
  text = 'Ein Netzwerktechniker soll Verbindungsprobleme in einem SOHO-Netzwerk beheben. Mehrere Workstations (PC-A, PC-B, PC-C) können keine Verbindung zum Dateiserver herstellen. Die IP-Konfiguration zeigt auf den Workstations Adressen im Bereich 169.254.x.x/16. Der Dateiserver ist unter 192.168.1.100/24 erreichbar. Analysieren Sie das Problem und bestimmen Sie Ursache und Lösung.',
  explanation = 'Lösung: 169.254.x.x/16 ist die APIPA-Range (Automatic Private IP Addressing). Geräte weisen sich selbst eine APIPA-Adresse zu, wenn kein DHCP-Server erreichbar ist. Ausgefallener Dienst: DHCP-Server. Behebung: DHCP-Server neu starten, dann auf Workstations ipconfig /renew (Windows) oder dhclient (Linux) ausführen. APIPA-Geräte und Geräte mit statischen IPs aus anderen Netzen können nicht kommunizieren — daher kein Dateiserver-Zugriff.',
  pbq_subtype = 'dropdown',
  pbq_config = '{"scenario_image": "data:image/svg+xml;base64,", "questions": [{"id": "q_apipa_ip", "label": "Welche IP-Adresse auf den Workstations weist auf ein Konfigurationsproblem hin?", "options": ["192.168.1.100 (Dateiserver)", "169.254.x.x / 16 (APIPA-Bereich)", "10.0.0.1 (Router)", "255.255.0.0 (Subnetzmaske)"], "correct": "169.254.x.x / 16 (APIPA-Bereich)", "explanation": "169.254.x.x/16 ist die APIPA-Range (Automatic Private IP Addressing, RFC 3927). Ein Gerät weist sich selbst eine APIPA-Adresse zu, wenn kein DHCP-Server erreichbar ist. Das bedeutet: der DHCP-Server ist ausgefallen oder nicht erreichbar."}, {"id": "q_failed_service", "label": "Welcher Netzwerkdienst ist ausgefallen und verursacht die APIPA-Adressen?", "options": ["DNS (Domain Name System)", "DHCP (Dynamic Host Configuration Protocol)", "NTP (Network Time Protocol)", "RADIUS (Authentication)"], "correct": "DHCP (Dynamic Host Configuration Protocol)", "explanation": "DHCP weist automatisch IP-Adressen, Subnetzmasken, Gateways und DNS-Server zu. Wenn der DHCP-Server nicht antwortet, fällt Windows/Linux auf APIPA zurück (169.254.x.x). APIPA-Geräte können nur innerhalb des gleichen Broadcast-Domains kommunizieren — nicht mit dem Dateiserver (192.168.1.100/24)."}, {"id": "q_solution", "label": "Welche Maßnahme behebt das Problem für alle betroffenen Workstations am schnellsten?", "options": ["Alle Workstations mit statischen IPs aus dem 192.168.1.0/24 Bereich konfigurieren", "DHCP-Server neu starten und auf den Workstations ipconfig /renew ausführen", "Das Netzwerkkabel an jeder Workstation neu stecken", "Den DNS-Server neu starten"], "correct": "DHCP-Server neu starten und auf den Workstations ipconfig /renew ausführen", "explanation": "Schnellste Lösung: DHCP-Server-Dienst neu starten (oder Server-Neustart falls nötig), dann auf jeder Workstation ''ipconfig /renew'' (Windows) oder ''dhclient -r && dhclient'' (Linux) ausführen, um einen neuen DHCP-Lease anzufordern. Statische IPs wären ein langsamerer und fehleranfälliger Workaround."}]}'::jsonb
WHERE id = 12472;

UPDATE oc_learning_questions SET
  text = 'Nach einem Stromausfall berichten Benutzer von Leistungsproblemen beim Zugriff auf Netzwerkressourcen. VoIP-Gespräche sind gestört. Das Netzwerk-Dashboard zeigt: WAN1 (100 Mbps, 24 ms Latenz, 9.5 ms Jitter) und WAN2 (50 Mbps, 18 ms Latenz, 2.1 ms Jitter). Die Geräte-Statusliste und die Traffic-Analyse sind auf dem Dashboard sichtbar. Analysieren Sie Dashboard-Daten und identifizieren Sie die Probleme.',
  explanation = 'Lösung: VoIP-Interface: WAN2 ist besser — VoIP braucht niedrigen Jitter (max. 30 ms nach ITU-T G.114). WAN2 hat 2.1 ms Jitter vs. WAN1 mit 9.5 ms. Bandbreite ist sekundär. Router-Problem: Router A (206.10.1.1) ist nach dem Stromausfall offline — Status FEHLER / Request Timed Out. Router B (206.10.1.2) läuft normal. Meiste Traffic-Workstation: 10.1.90.53 mit 4.820 kb/s dominiert den Workstation-Traffic. 206.x Adressen sind WAN-Router, keine Workstations.',
  pbq_subtype = 'dropdown',
  pbq_config = '{"scenario_image": "data:image/svg+xml;base64,", "questions": [{"id": "q_voip_wan", "label": "Welches WAN-Interface eignet sich für VoIP-Datenverkehr?", "options": ["WAN1 (100 Mbps, 24 ms Latenz, 9.5 ms Jitter)", "WAN2 (50 Mbps, 18 ms Latenz, 2.1 ms Jitter)", "Beide sind gleichwertig für VoIP"], "correct": "WAN2 (50 Mbps, 18 ms Latenz, 2.1 ms Jitter)", "explanation": "VoIP ist jitterempfindlich. Der empfohlene Maximalwert liegt bei 30 ms Jitter (ITU-T G.114). WAN2 hat 2.1 ms Jitter gegenüber WAN1 mit 9.5 ms — WAN2 ist trotz geringerer Bandbreite die bessere Wahl. Bandbreite ist für VoIP (ca. 64–128 kbps pro Gespräch) kein limitierender Faktor."}, {"id": "q_router_problem", "label": "Welcher Router hat nach dem Stromausfall Verbindungsprobleme?", "options": ["Router A (206.10.1.1)", "Router B (206.10.1.2)", "Wireless Controller (192.168.x)", "DNS Server"], "correct": "Router A (206.10.1.1)", "explanation": "In der Geräte-Status-Tabelle erscheint Router A (206.10.1.1) mit Status FEHLER / Request Timed Out. Router B (206.10.1.2) und alle anderen Geräte sind erreichbar. 206.x sind öffentliche WAN-Router-Adressen — die internen Workstations (10.1.x.x) sind keine Router."}, {"id": "q_most_traffic", "label": "Welche Workstation generiert den meisten Traffic?", "options": ["10.1.99.28 (840 kb/s)", "10.1.90.53 (4.820 kb/s)", "10.1.50.14 (320 kb/s)", "206.10.1.2 (Router B)"], "correct": "10.1.90.53 (4.820 kb/s)", "explanation": "Die Traffic-Tabelle zeigt: 10.1.90.53 mit 4.820 kb/s ist die Spitze unter den Workstations (10.1.x.x Bereich). 206.x-Adressen sind Router, keine Workstations. 10.1.99.28 mit 840 kb/s ist an zweiter Stelle, aber deutlich weniger."}]}'::jsonb
WHERE id = 12464;

COMMIT;

